from pathlib import Path
import json,hashlib,random,time,ast,shutil
R=Path(__file__).resolve().parent;P=R.parent
assert not (R/'protocol.json').exists()
for n in ['engine.py','analyze.py']:ast.parse((R/n).read_text())
h=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
sources=json.loads((P/'matched_rate_v3/protocol.json').read_text())['sources']
assert all(h(f)==v for f,v in sources.items())
sources.update({str(R/n):h(R/n) for n in ['engine.py','analyze.py']})
seeds=[3101,3202,3303,3404,3505];rng=random.Random(86002);jobs=[]
for seed in seeds:
 block=[[seed,rate,arm] for rate in [.002,.008] for arm in ['coarse32','phys32']];rng.shuffle(block);jobs+=block
p={'frozen_at_unix':time.time(),'study':'fixed_updates_v12','architecture':'FNO(8,8,32), same frozen source, 532993 parameters','device':'CPU','threads':1,'arms':['coarse32','phys32'],'rates':[.002,.008],'seeds':seeds,'parameter_seed_offset':101000,'batch_seed_offset':190000,'pool':8192,'nominal_batch':8,'deduplicate_within_batch':True,'initial_hf':32,'max_updates':1400,'endpoints':[800,1400],'independent_trajectories':20,'dependent_endpoints':40,'validation_every':100,'validation_includes_initial':True,'selection':'Minimum validation relative_l2, earliest tie; primary last iterate at exact endpoint, secondary best validation iterate','optimizer':'AdamW, weight_decay1e-4; 0.5 mean squared error on scaled fields','lr_tau_updates':160,'lr_schedule':'eta(step)=eta0/(1+(step-1)/160), step starts at1; common prefix for both endpoints. Tau160 approximates60s/0.373s historic CPU update probe, not tuned to outcomes; not a replay of old wall-time schedule.','reference_seeds':[87001,87002,87003],'reference_counts':[32,128,64],'ood_multiplier':1.25,'nf':512,'nc':32,'gain':2,'grid':129,'jobs':jobs,'sources':sources,'source_policy':'Never mutate frozen computation. Source mismatch stops execution. Explicitly version any required runtime repair, retaining failed outputs.','precompute':'Full 1400-step input sequence fixed first; generate exactly its union plus first32 HF upfront. Both target strategies and both rates use same pool, sequence and initialization within seed. Actual setup/input/target costs separate.','accounting':'Not equal wall-clock. Labels shared once per seed across rates, expenses not duplicated. Training/validation/checkpoint/export and offline evaluation times recorded. Competing Python CPU>30% sampled every15s, no run exclusion.','retention':'All five seeds, both rates, last+selected, ID+OOD, both endpoints. Nonfinite failures retained with missing endpoints; no replacement, additional seeds, tuning, outcome-based stopping or sample filtering. Runtime exceptions stop, retain incomplete directories for audit.','analysis':'Paired corrected-minus-coarse at both endpoints/rates primary on last ID; selected and OOD secondary. Within-policy 1400-800 and target-by-update/rate interactions reported. Five-unit paired t95 descriptive, exact sign test descriptive; no multiplicity-adjusted or universal significance claim.','scope':'A controlled target-strategy comparison conditional on fixed update/exposure sequence and step schedule; not a causal decomposition of old deadline gaps, not independent exposure-count mediation, not HF128 mechanism. Both endpoints share trajectories.','no_test_based_choices':True}
(R/'protocol.json').write_text(json.dumps(p,indent=2));(R/'protocol.sha256').write_text(h(R/'protocol.json')+'\n')
shutil.copytree(P/'manuscript/paper',R/'baseline_manuscript',ignore=shutil.ignore_patterns('._*'))
(R/'README.md').write_text('''# Frozen fixed-update mechanism diagnostic v12

Protocol and engine/analysis SHA-256 frozen before references, labels or model fitting. 20 serial trajectories, two correlated endpoints each, five new paired pools, both initial rates. Primary last iterates; secondary validation-selected models. No extra seeds or tuning. No performance-based exclusions. All up-front target and input costs separately recorded. See protocol.json for estimands, seeds, schedule, stopping and failure policy.

Runtime: existing bundled Python and original project dependencies; launch engine.py. It uses a lock and refuses to overwrite incomplete outputs. A completed job is resumed only from its saved result; incomplete jobs require explicit audit, never silent restart. analyze.py is frozen and performs no manuscript edits. The final editorial review must examine all outcomes and update paper and submission materials; completion.json alone is not editorial completion.
''')
print(json.dumps({'protocol_sha256':h(R/'protocol.json'),'jobs':jobs,'frozen_sources':len(sources)},indent=2))
